#!/bin/sh
# Load B's real 353-paper pilot (generated by pipeline/pilot_to_seed.py).
# SCHOLARQL_SEED=none starts with empty tables instead.
if [ "${SCHOLARQL_SEED:-pilot}" = "none" ]; then
  echo "SCHOLARQL_SEED=none: skipping seed data"
else
  psql -v ON_ERROR_STOP=1 -q --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" \
    -f /scholarql-db/seed/pilot.sql || exit 1
fi
